const inputItems = $input.all();
const first = inputItems[0]?.json ?? {};
const sourceRows = Array.isArray(first.records) ? first.records : inputItems.map((item) => item.json);
const records = sourceRows.map((record, sourceIndex) => {
  const sourceUrl = "/" + String(record.sourceUrl ?? "")
    .trim()
    .replace(/^\/+/, "")
    .replace(/\/+/g, "/")
    .replace(/\/$/, "");
  return {
    sourceIndex,
    title: String(record.title ?? "").trim(),
    suppliedSlug: String(record.slug ?? "").trim().toLowerCase(),
    sourceUrl,
  };
});
return [{ json: { ...first, sourceRows: sourceRows.length, records } }];

const item = $input.all()[0]?.json ?? {};
const slugify = (value) => String(value)
  .normalize("NFKD")
  .replace(/[\u0300-\u036f]/g, "")
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, "-")
  .replace(/^-|-$/g, "");
const counts = new Map();
const collisions = [];
const accepted = [];
const rejected = [];
for (const record of item.records ?? []) {
  const validSupplied = /^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(record.suppliedSlug);
  const baseSlug = validSupplied ? record.suppliedSlug : slugify(record.title);
  if (!record.title && !baseSlug) {
    rejected.push({
      sourceIndex: record.sourceIndex,
      title: record.title,
      sourceUrl: record.sourceUrl,
      reasonCodes: ["missing_required_field"],
    });
    continue;
  }
  const count = (counts.get(baseSlug) ?? 0) + 1;
  counts.set(baseSlug, count);
  const slug = count === 1 ? baseSlug : baseSlug + "-" + count;
  if (count > 1) collisions.push({ baseSlug, resolvedSlug: slug, sourceIndex: record.sourceIndex });
  accepted.push({ ...record, slug });
}
return [{ json: { ...item, records: accepted, rejected, collisions } }];

const item = $input.all()[0]?.json ?? {};
const statusCode = Number(item.redirectStatusCode ?? 301);
const contentRows = (item.records ?? []).map((record) => ({
  sourceIndex: record.sourceIndex,
  title: record.title,
  slug: record.slug,
  destinationPath: "/" + record.slug,
}));
const redirects = (item.records ?? []).map((record) => ({
  from: record.sourceUrl,
  to: "/" + record.slug,
  statusCode,
}));
const collisions = item.collisions ?? [];
const rejected = item.rejected ?? [];
const summary = {
  sourceRows: item.sourceRows ?? 0,
  contentRows: contentRows.length,
  redirects: redirects.length,
  collisions: collisions.length,
  rejected: rejected.length,
};
const status = rejected.length === 0 && collisions.length === 0 ? "ready" : "review_required";
return [{ json: { contentRows, redirects, collisions, rejected, summary, status } }];
